  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = fps * durationInSeconds;

  // Background configurations - overlays are transparent by default
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Keyframe Timing definitions
  const startFrame = 25;
  const endFrame = totalFrames - 25;

  // Flight path progress driven by a beautifully tuned custom Easing curve
  const progress = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 0.1, 0.25, 1),
  });

  // Waypoint positions perfectly scaled and responsive to any viewport
  const p0 = { x: width * 0.15, y: height * 0.5 + height * 0.02 }; 
  const p1 = { x: width * 0.5, y: height * 0.5 - height * 0.06 };  
  const p2 = { x: width * 0.85, y: height * 0.5 + height * 0.02 };  

  // Quad Bezier computation for plane position (x, y) & heading tangent at current progress
  const p = progress;
  const planeX = (1 - p) * (1 - p) * p0.x + 2 * (1 - p) * p * p1.x + p * p * p2.x;
  const planeY = (1 - p) * (1 - p) * p0.y + 2 * (1 - p) * p * p1.y + p * p * p2.y;

  const dx = 2 * (1 - p) * (p1.x - p0.x) + 2 * p * (p2.x - p1.x);
  const dy = 2 * (1 - p) * (p1.y - p0.y) + 2 * p * (p2.y - p1.y);
  const planeAngle = (Math.atan2(dy, dx) * 180) / Math.PI;

  const sacOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sacTranslateY = interpolate(frame, [10, 25], [10, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });

